insert into public.art_movements (slug, name_ja, name_en, region, start_year, end_year, summary, body, source_url)
values ('song-yuan', '宋元画', 'Song and Yuan painting', 'east_asia', 960, 1368,
        '中国の宋と元の時代の絵画。雄大な山水画や禅僧の水墨画が生まれ、日本や朝鮮の絵画の手本になりました。', '宋の時代（960〜1279年）は、中国絵画の大きな転換点でした。唐の時代までは色を塗った人物画が中心でしたが、宋では山や川を描く「山水画」と、花や鳥を描く「花鳥画」の形が整い、とくに山水画が中国絵画を代表する分野になりました。宮廷には画院という画家の役所があり、皇帝の徽宗のように自ら筆をとる人もいました。

北宋（960〜1127年）では、范寛や郭煕が、画面の中央にそびえる大きな山を描きました。郭煕は、見上げる・見通す・見下ろすという三つの視点（三遠法）を画論にまとめています。南宋（1127〜1279年）になると、馬遠や夏珪が、景色を画面の片隅に寄せて大きな余白を残す構図を完成させました。同じころ、牧谿や梁楷は、少ない筆の運びで人物や果物を描く水墨画を残しています。元の時代（1271〜1368年）には、黄公望・倪瓚など「元末四大家」と呼ばれる文人画家が、北宋以前の山水を手本に、自分の心を映す絵を描きました。

これらの絵は鎌倉・室町時代に禅僧や貿易を通して日本へ渡り、足利将軍家などが大切に集めました。牧谿や梁楷は、中国よりも日本で高く評価されたといわれます。作品を見るときは、山の大きさをどう感じさせているか、余白や霧がどんな奥行きを生んでいるか、墨の濃い・薄いの使い分けに注目してみてください。', 'https://ja.wikipedia.org/wiki/%E5%AE%8B%E5%85%83%E7%94%BB')
