insert into public.art_movements (slug, name_ja, name_en, region, start_year, end_year, summary, body, source_url)
values ('yamato-e', '大和絵', 'Yamato-e', 'japan', 900, 1868,
        '日本の物語や四季、名所を描いた日本風の絵画。平安時代に生まれ、絵巻物を中心に発展しました。', '大和絵（やまと絵）は、中国風の絵画「唐絵（からえ）」に対して生まれた、日本風の絵画です。894年に遣唐使が止められたあと、10世紀には仮名文字や和歌が栄える国風文化が育ち、大和絵もこのころに現れたと考えられています。文献にこの言葉が初めて出てくるのは999年です。はじめは「日本の物事を描いた絵」という主題による区別でしたが、14世紀以降は絵の様式や流派を指す言葉にもなりました。

大和絵の主な題材は、四季の移り変わり、月ごとの行事、名所、そして物語です。12世紀には『源氏物語絵巻』『伴大納言絵巻』『信貴山縁起』『鳥獣人物戯画』の四大絵巻が作られました。屋根を取り払って室内をのぞき込むように描く「吹抜屋台」や、細い目とくの字の鼻で顔を表す「引目鉤鼻」など、独特の表し方が生まれています。鎌倉時代には寺社の由来や高僧の伝記を描く絵巻が数多く作られ、藤原隆信・信実父子らが実在の人物を写した肖像画（似絵）を描きました。室町時代には土佐光信が土佐派を盛り上げ、江戸時代には土佐派と住吉派が伝統を受け継ぎました。

見るときは、絵巻を右から左へ少しずつ広げるつもりで、時間の流れや場面のつながりを追ってみてください。やわらかな線、明るい色、金や銀の装飾にも注目すると、後の琳派や近代の日本画へ続く感覚が見えてきます。', 'https://ja.wikipedia.org/wiki/%E5%A4%A7%E5%92%8C%E7%B5%B5')
on conflict (slug) do update set
    name_ja = excluded.name_ja,
    name_en = excluded.name_en,
    region = excluded.region,
    start_year = excluded.start_year,
    end_year = excluded.end_year,
    summary = excluded.summary,
    body = excluded.body,
    source_url = excluded.source_url,
    updated_at = now();

insert into public.art_movements (slug, name_ja, name_en, region, start_year, end_year, summary, body, source_url)
values ('suiboku', '水墨画', 'Japanese ink painting', 'japan', 1280, 1600,
        '墨の濃淡やにじみで描く絵画。鎌倉時代に禅とともに中国から伝わり、室町時代の雪舟らが日本独自の画風を築きました。', '水墨画は、墨の線だけでなく、濃淡やにじみ、かすれを使って山や水、人物を表す絵画です。中国で唐の時代の後半に生まれ、宋・元の時代に大きく発展しました。日本では鎌倉時代、禅宗の僧が中国と行き来するようになると、宋や元の新しい絵が禅とともに伝わりました。13世紀末から14世紀ごろの作品は「初期水墨画」と呼ばれ、禅僧の肖像（頂相）や達磨の図などが描かれています。

室町時代は日本の水墨画の最盛期です。足利将軍家の保護のもと、京都の相国寺から如拙、周文、雪舟といった画僧が出ました。将軍家は牧谿・梁楷・馬遠・夏珪など南宋の絵を「唐物」として熱心に集め、日本の画家はそれを手本に学びました。15世紀前半には、縦長の画面の下に山水を描き、上に禅僧たちが漢詩を書き込む「詩画軸」が流行します。その後、雪舟は明へ渡って学び、帰国後は日本各地を旅して、『天橋立図』のように日本の実際の風景を描きました。桃山時代には長谷川等伯が『松林図屏風』で霧に包まれた松林を描き、水墨画の新しい境地を開いています。

作品を見るときは、塗られていない白い部分が、霧や水、光としてどのように働いているかに注目してください。筆の勢い、墨の濃さの重なり、画面に書かれた漢詩との関係も見どころです。', 'https://ja.wikipedia.org/wiki/%E6%B0%B4%E5%A2%A8%E7%94%BB')
on conflict (slug) do update set
    name_ja = excluded.name_ja,
    name_en = excluded.name_en,
    region = excluded.region,
    start_year = excluded.start_year,
    end_year = excluded.end_year,
    summary = excluded.summary,
    body = excluded.body,
    source_url = excluded.source_url,
    updated_at = now();

insert into public.art_movements (slug, name_ja, name_en, region, start_year, end_year, summary, body, source_url)
values ('kano', '狩野派', 'Kanō school', 'japan', 1460, 1868,
        '室町時代から江戸時代末まで約400年続いた日本最大の画派。時の権力者に仕え、城や寺の障壁画を描きました。', '狩野派は、室町幕府の御用絵師となった狩野正信を祖とする画家の一族と、その弟子たちの集団です。正信は1463年には京都で絵師として活動しており、雪舟らを生んだ相国寺の画僧たちのあとを継ぐ形で、将軍家に仕えました。その後、狩野派は織田信長、豊臣秀吉、徳川将軍家と、時代ごとの権力者に仕え、江戸時代の終わりまで画壇の中心にあり続けました。

二代目の狩野元信は、中国風の水墨画（漢画）の描き方を整理し、そこに大和絵の色彩や技法を取り入れて、狩野派の画風を完成させました。描き方を「真・行・草」の三つの型にまとめたことで、多くの弟子が同じ水準で共同制作できるようになります。元信の孫の狩野永徳は、安土城や大坂城の障壁画を手がけ、金地に巨木や唐獅子を大きく描く豪快な画風で知られます。江戸時代には狩野探幽が江戸に拠点を移し、江戸城や二条城の障壁画を指揮しました。弟子たちは手本（粉本）を写して学んだため、個性に欠けるという批判もありますが、高い技術を受け継ぐ仕組みでもありました。明治時代の狩野芳崖や橋本雅邦も、この狩野派の出身です。

見るときは、建物の部屋ごとに描かれた襖や屏風が、空間全体をどう飾っているかを想像してみてください。墨の力強い線と、金箔や鮮やかな色の組み合わせも見どころです。', 'https://ja.wikipedia.org/wiki/%E7%8B%A9%E9%87%8E%E6%B4%BE')
on conflict (slug) do update set
    name_ja = excluded.name_ja,
    name_en = excluded.name_en,
    region = excluded.region,
    start_year = excluded.start_year,
    end_year = excluded.end_year,
    summary = excluded.summary,
    body = excluded.body,
    source_url = excluded.source_url,
    updated_at = now();

insert into public.art_movements (slug, name_ja, name_en, region, start_year, end_year, summary, body, source_url)
values ('rinpa', '琳派', 'Rinpa', 'japan', 1600, null,
        '本阿弥光悦と俵屋宗達に始まり、尾形光琳や酒井抱一が受け継いだ装飾的な画風。金地と大胆な構図が特徴です。', '琳派は、桃山時代の終わりから江戸時代にかけて生まれた、装飾性の豊かな絵画や工芸の流れです。京都で書や工芸に通じた本阿弥光悦と、扇や料紙の絵を手がけた俵屋宗達が始まりとされます。大和絵の伝統を土台にしながら、絵画だけでなく書や蒔絵、陶芸までを一つの美意識でまとめた点が特色です。

琳派のもう一つの特色は、親から子、師から弟子へと直接受け継ぐ他の流派と違い、時代も場所も離れた人が、前の人の作品に心をひかれて学ぶ「私淑」によってつながっていることです。宗達からおよそ100年後、京都の尾形光琳が宗達の絵に学び、弟の乾山とともにこの画風を発展させました。さらに約100年後には、江戸の酒井抱一が光琳に傾倒し、鈴木其一らとともに江戸で琳派を広めました。『風神雷神図』は宗達、光琳、抱一がそれぞれ描いており、比べて見ることができます。技法では、金や銀の箔を使った背景、型紙のような繰り返しの模様、乾ききらない絵の具に別の色を垂らしてにじませる「たらしこみ」がよく知られています。

見るときは、草花や波がどのように単純な形にまとめられ、画面にリズムを生んでいるかに注目してください。近代の日本画やデザインにも、琳派の考え方は受け継がれています。', 'https://ja.wikipedia.org/wiki/%E7%90%B3%E6%B4%BE')
on conflict (slug) do update set
    name_ja = excluded.name_ja,
    name_en = excluded.name_en,
    region = excluded.region,
    start_year = excluded.start_year,
    end_year = excluded.end_year,
    summary = excluded.summary,
    body = excluded.body,
    source_url = excluded.source_url,
    updated_at = now();

insert into public.art_movements (slug, name_ja, name_en, region, start_year, end_year, summary, body, source_url)
values ('ukiyo-e', '浮世絵', 'Ukiyo-e', 'japan', 1660, 1900,
        '江戸の町人文化の中で生まれた風俗画。木版画で大量に刷られ、美人画・役者絵・風景画が人々に親しまれました。', '浮世絵は、江戸時代の初めに成立した、当時の暮らしや流行を描く絵です。「浮世」には「今の世の中」「当世風」という意味があります。それまで絵画の主な担い手は、公家や大名に仕える土佐派や狩野派でした。1657年の明暦の大火のあと江戸の町人が経済力をつけると、町人の好みに合った風俗画が求められるようになりました。菱川師宣は、こうした風俗画を一枚の独立した作品として描き、浮世絵の祖と呼ばれています。

浮世絵には筆で描いた肉筆画と木版画があり、とくに版画が庶民に広まりました。版元が企画し、絵師・彫師・摺師が分業することで、安い値段で大量に売ることができたからです。1760年代には鈴木春信らが多くの色を重ねて摺る「錦絵」を生み出しました。題材は遊里の美人や歌舞伎役者に始まり、喜多川歌麿の美人画、東洲斎写楽の役者絵へと続きます。19世紀には、葛飾北斎の『富嶽三十六景』や歌川広重の『東海道五十三次』が、輸入顔料のベロ藍を使った風景画として人気を集めました。

1867年のパリ万国博覧会などを通じて浮世絵はヨーロッパに知られ、ジャポニスムのきっかけとなり、ゴッホやドガら、印象派やその周辺の画家に影響を与えました。見るときは、平らな色面、思い切った切り取り方、前景を大きく描く構図に注目してみてください。', 'https://ja.wikipedia.org/wiki/%E6%B5%AE%E4%B8%96%E7%B5%B5')
on conflict (slug) do update set
    name_ja = excluded.name_ja,
    name_en = excluded.name_en,
    region = excluded.region,
    start_year = excluded.start_year,
    end_year = excluded.end_year,
    summary = excluded.summary,
    body = excluded.body,
    source_url = excluded.source_url,
    updated_at = now();

insert into public.art_movements (slug, name_ja, name_en, region, start_year, end_year, summary, body, source_url)
values ('yoga-meiji', '洋画', 'Western-style painting in modern Japan (yōga)', 'japan', 1876, 1945,
        '明治時代に西洋から本格的に学ばれた油彩画などの絵画。日本画と並ぶ近代日本絵画のもう一つの柱になりました。', '日本で「洋画」というと、明治維新以降の日本の画家が描いた、西洋風の油彩画や水彩画を指します。江戸時代にも西洋の陰影法や遠近法を学んだ画家はいましたが、本格的な取り組みは明治時代に始まりました。政府は西洋式の美術を取り入れようとして、1876年に工部美術学校を開き、イタリアから画家のフォンタネージを招きました。浅井忠らがここで学んでいます。それより前から、高橋由一は油絵具で身近なものを写実的に描く試みを続けていました。

1880年代には伝統美術を重んじる動きが強まり、1889年に開校した東京美術学校では、はじめ西洋画が教えられませんでした。これに対して洋画家たちは同じ年に明治美術会をつくり、日本で最初の洋風美術団体として活動しました。ドイツで学んだ原田直次郎は、西洋の油彩技法で観音を描くなど、新しい表現を試みています。大きな転機は、フランスでラファエル・コランに学んだ黒田清輝が1893年に帰国したことでした。黒田は屋外の光を明るい色で表す外光派の画風を伝え、1896年に白馬会を結成し、東京美術学校の西洋画科で教えました。この流れから、神話を題材にした青木繁や、藤島武二らが育ちます。1907年からは政府の展覧会（文展）で、日本画と洋画が並んで展示されました。

見るときは、光と影の付け方、空気の明るさ、日本の人物や風景を油絵具でどう描こうとしたかに注目してください。', 'https://ja.wikipedia.org/wiki/%E6%B4%8B%E7%94%BB%E5%AE%B6')
on conflict (slug) do update set
    name_ja = excluded.name_ja,
    name_en = excluded.name_en,
    region = excluded.region,
    start_year = excluded.start_year,
    end_year = excluded.end_year,
    summary = excluded.summary,
    body = excluded.body,
    source_url = excluded.source_url,
    updated_at = now();

insert into public.art_movements (slug, name_ja, name_en, region, start_year, end_year, summary, body, source_url)
values ('nihonga', '日本画', 'Nihonga', 'japan', 1882, null,
        '明治時代、西洋から来た洋画に対して生まれた言葉。岩絵具や和紙・絹など伝統の材料を使い、新しい表現を目指した絵画です。', '日本画は、明治時代に西洋の油彩画（洋画）が広まる中で生まれた考え方です。アメリカから来日したフェノロサは1882年の講演で日本の絵画の良さを説き、その訳語として「日本画」という言葉が使われました。明治のはじめは西洋画への転向が進み、狩野派など幕府を支えにしていた画派は力を失っていましたが、フェノロサと岡倉天心は、伝統を生かした新しい絵画を育てようとしました。

1889年に開校した東京美術学校では、狩野派出身の橋本雅邦らが教え、第1期生に横山大観がいました。雅邦の兄弟子の狩野芳崖は、フェノロサとともに日本画の革新に取り組み、『悲母観音』を残しています。1898年、天心は大観、下村観山、菱田春草らと日本美術院を結成しました。大観と春草は輪郭線を使わずに色のぼかしで空気や光を表す技法を試み、当時は「朦朧体」と批判されましたが、新しい表現として後に評価されます。京都では竹内栖鳳がヨーロッパを訪れて西洋の写実も取り入れ、上村松園は女性の姿を気品ある美人画に描きました。日本画は古い技法を守るだけでなく、西洋画から学べるところは学び、それと並び立つ絵画を目指したのです。

日本画では、鉱物を砕いた岩絵具を膠で溶き、和紙や絹に塗り重ねます。見るときは、絵具の粒が生む独特の質感や、余白、線の生かし方に注目してください。', 'https://ja.wikipedia.org/wiki/%E6%97%A5%E6%9C%AC%E7%94%BB')
on conflict (slug) do update set
    name_ja = excluded.name_ja,
    name_en = excluded.name_en,
    region = excluded.region,
    start_year = excluded.start_year,
    end_year = excluded.end_year,
    summary = excluded.summary,
    body = excluded.body,
    source_url = excluded.source_url,
    updated_at = now();

insert into public.art_movements (slug, name_ja, name_en, region, start_year, end_year, summary, body, source_url)
values ('gutai', '具体美術協会', 'Gutai Art Association', 'japan', 1954, 1972,
        '1954年に兵庫県芦屋市で吉原治良を中心に結成された前衛美術グループ。行為や物質そのものを生かした表現で知られます。', '具体美術協会（具体）は、戦前から活躍していた画家の吉原治良を中心に、1954年に兵庫県芦屋市で結成された美術グループです。吉原は若い作家たちに「人の真似をするな。今までにないものをつくれ」と教えました。1955年には白髪一雄、村上三郎、金山明、田中敦子らが加わり、元永定正も参加します。吉原は1951年に日本でジャクソン・ポロックの作品を見て強い印象を受けており、1956年の「具体美術宣言」では、素材と正面から向き合う作家としてポロックとフランスのジョルジュ・マチウの名を挙げています。

具体の作家たちは、絵の具や紙、泥、光といった物質そのものの性質と、それに働きかける体の行為を大切にしました。白髪一雄は天井から吊るしたロープにつかまり、足で絵の具をかき広げて描きました。1955年には泥の中で体ごと格闘するパフォーマンスも行っています。村上三郎は紙を張った枠を体で突き破り、田中敦子は電球をつないだ「電気服」を発表しました。芦屋の松林での野外展や、舞台を使った展覧会など、発表の場も型破りでした。フランスの批評家ミシェル・タピエは、具体をアンフォルメル（不定形の抽象絵画）の日本での例として海外に紹介しています。また、アメリカのアラン・カプローは、自著でハプニングを論じる際に具体を取り上げました。1972年に吉原が亡くなると、協会は解散しました。

作品を見るときは、完成した画面だけでなく、それがどんな体の動きや出来事から生まれたのかを想像してみてください。', 'https://ja.wikipedia.org/wiki/%E5%85%B7%E4%BD%93%E7%BE%8E%E8%A1%93%E5%8D%94%E4%BC%9A')
on conflict (slug) do update set
    name_ja = excluded.name_ja,
    name_en = excluded.name_en,
    region = excluded.region,
    start_year = excluded.start_year,
    end_year = excluded.end_year,
    summary = excluded.summary,
    body = excluded.body,
    source_url = excluded.source_url,
    updated_at = now();

insert into public.art_movements (slug, name_ja, name_en, region, start_year, end_year, summary, body, source_url)
values ('mono-ha', 'もの派', 'Mono-ha', 'japan', 1968, 1975,
        '石や木、紙、鉄板などの「もの」をほとんど手を加えずに置き、ものと空間の関係を見せた1960年代末〜70年代の動向です。', 'もの派は、1960年代の終わりから1970年代半ばにかけて日本で起きた現代美術の動きです。きっかけは、1968年に関根伸夫が発表した『位相―大地』でした。地面に円筒形の穴を掘り、掘り出した土を同じ形に固めて隣に置いたこの作品を、李禹煥（リ・ウファン）が新しい視点で評価し、理論づけたことから始まります。二人の研究会に、多摩美術大学で斎藤義重に学んだ吉田克朗、成田克彦、小清水漸、菅木志雄が加わり、他の大学の榎倉康二、高山登、原口典之らも作品を発表しました。

それまでの日本の前衛美術では、芸術そのものを否定するような「反芸術」の傾向が主流でした。もの派の作家たちはこれに反発し、石、木、紙、綿、鉄板、パラフィンといった素材を、ほとんど加工せずに単独で、あるいは組み合わせて置きました。作家が何かを作り込むのではなく、ものと空間、ものと見る人の関係そのものを見せようとしたのです。李禹煥は「あるがままの世界との出会い」を理論の柱とし、関根伸夫は老荘思想の影響を受けた視点から作品を作るなど、考え方には幅がありました。1970年夏ごろからは、作家たちはそれぞれの方向へ分かれていきます。1980年代以降、もの派は海外で再評価され、同じ時代にイタリアで起きたアルテ・ポーヴェラや、アメリカのアンチ・フォームとの共通点が研究されています。

見るときは、素材の重さや手ざわり、置かれた位置、まわりの空間との緊張関係に注目してください。', 'https://ja.wikipedia.org/wiki/%E3%82%82%E3%81%AE%E6%B4%BE')
on conflict (slug) do update set
    name_ja = excluded.name_ja,
    name_en = excluded.name_en,
    region = excluded.region,
    start_year = excluded.start_year,
    end_year = excluded.end_year,
    summary = excluded.summary,
    body = excluded.body,
    source_url = excluded.source_url,
    updated_at = now();

insert into public.art_movements (slug, name_ja, name_en, region, start_year, end_year, summary, body, source_url)
values ('joseon', '朝鮮王朝の絵画', 'Painting of the Joseon dynasty', 'east_asia', 1392, 1897,
        '1392年に始まる朝鮮王朝で描かれた絵画。中国の宋・元の絵を手本にしつつ、朝鮮の実景を描く真景山水など独自の表現を育てました。', '朝鮮王朝は1392年に建てられ、500年以上続いた王朝です。王朝は中国の画院にならって「図画署」という役所を置き、そこに属する画員と、学問を修めた文人たちが絵画の主な担い手になりました。前の高麗の時代には仏画が盛んでしたが、儒教を重んじた朝鮮王朝では仏教がおさえられ、山水画や文人の絵が中心になります。

前期の山水画は、中国の宋・元の絵を古典として学びました。15世紀の安堅は、北宋の郭煕の画風を受け継ぎ、王子の安平大君が夢に見た理想郷を『夢遊桃源図』（1447年）に描いています。後期になると、中国の名所ではなく朝鮮の実際の山や川を描く「真景山水画」が生まれました。鄭敾は金剛山など各地の名勝を訪ね歩き、濃い墨と淡い墨の強い対比で岩肌を表す画風を開きました。18世紀には金弘道や申潤福が、庶民や都市の暮らしを生き生きと描く風俗画で知られます。19世紀には金正喜が、学問と書に裏打ちされた文人画『歳寒図』を残しました。19世紀後半の張承業は、金弘道・申潤福とあわせて「三園」と呼ばれる画家の一人です。また、専門の画家ではない人々が、生活の場を飾るために「民画」を描きました。

作品を見るときは、中国の手本からどこを受け継ぎ、どこで朝鮮の風景や暮らしに目を向けたのかに注目すると、日本や中国の絵との違いが見えてきます。', 'https://www.fukuoka-art-museum.jp/exhibition/paintings_from_koreas_joseon_dynasty/')
on conflict (slug) do update set
    name_ja = excluded.name_ja,
    name_en = excluded.name_en,
    region = excluded.region,
    start_year = excluded.start_year,
    end_year = excluded.end_year,
    summary = excluded.summary,
    body = excluded.body,
    source_url = excluded.source_url,
    updated_at = now();

