insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('伴大納言絵詞', 'Ban Dainagon Ekotoba', '常盤光長', 'Tokiwa Mitsunaga',
        1151,
        (select slug from public.art_movements where slug = 'yamato-e'),
        '出光美術館', 'https://upload.wikimedia.org/wikipedia/commons/8/87/Ban_Dainagon_Ekotoba_-_Crowd_and_a_gate.jpg', '866年の応天門の変を題材にした平安時代末期の絵巻で、四大絵巻の一つに数えられます。後白河法皇が常盤光長に描かせたと推定されていますが、制作年ははっきりしていません。燃え上がる応天門と、それを見上げて騒ぐ大勢の人々の表情や動きが、生き生きと描かれています。子どもの喧嘩から事件の真相が明らかになる場面では、一つの画面に時間の違う出来事を続けて描く「異時同図法」が使われています。物語を絵で語る大和絵の力をよく示す作品です。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('一遍聖絵', 'Ippen Shōnin Eden', '円伊', 'En''i',
        1299,
        (select slug from public.art_movements where slug = 'yamato-e'),
        '清浄光寺（遊行寺）・東京国立博物館', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7e/Ippen_Biography_3.jpg/960px-Ippen_Biography_3.jpg', '時宗を開いた一遍の生涯と旅を描いた全12巻の絵巻で、1299年に弟子の聖戒が詞書を書き、画僧の円伊が絵を描いたと奥書に記されています。一遍の旅は九州から東北にまで及び、各地の寺社や町、四季の景色が丁寧に描かれました。人物を小さく、背景の自然を大きく扱っているのが特徴です。山水の描き方には中国・宋の絵画の影響が指摘されており、大和絵の伝統に外から来た表現が加わり始めた鎌倉時代の様子がうかがえます。国宝に指定されています。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('石山寺縁起絵巻', 'Ishiyamadera engi emaki', '高階隆兼', 'Takashina Takakane',
        1324,
        (select slug from public.art_movements where slug = 'yamato-e'),
        '石山寺', 'https://upload.wikimedia.org/wikipedia/commons/a/a9/Ishiyamadera_engi_emaki_-_Scroll_3_Section_1.JPG', '滋賀県の石山寺が建てられた由来と、本尊の観音菩薩の霊験を描いた全7巻の絵巻です。第1巻から第3巻は鎌倉時代末の正中年間（1324〜26年）ごろ、宮廷の絵師・高階隆兼の工房で描かれたとみられます。残りの巻はずっと後に補われ、全巻がそろったのは1805年ごろでした。寺の歴史だけでなく、貴族や庶民の暮らしぶりもよくわかるため、歴史の資料としても大切にされています。鎌倉時代に盛んになった寺社縁起絵巻の代表例です。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('清水寺縁起絵巻', 'Kiyomizu-dera Engi Emaki', '土佐光信', 'Tosa Mitsunobu',
        1517,
        (select slug from public.art_movements where slug = 'yamato-e'),
        '東京国立博物館', 'https://upload.wikimedia.org/wikipedia/commons/a/a7/Kiyomizudera_engi_emaki_-_Scroll1_Pic3.jpg', '京都・清水寺の創建と、本尊の千手観音にまつわる霊験の物語を描いた3巻の絵巻で、1517年に制作されました。絵を描いたのは、室町時代に土佐派を盛り上げ「中興の祖」とされる土佐光信です。光信は公家や武家、寺社の求めに応じて多くの絵を描き、大和絵の題材や技法を広げました。平安・鎌倉時代から続く絵巻の形式を、室町時代の宮廷絵師が受け継いだ作品として見ることができます。この後、土佐派は狩野派と並ぶ流派として江戸時代まで続きました。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('瓢鮎図', 'Catching a catfish with a gourd', '如拙', 'Josetsu',
        1415,
        (select slug from public.art_movements where slug = 'suiboku'),
        '退蔵院（妙心寺）', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/f/fb/Hy%C3%B4nen_zu_by_Josetsu.jpg/960px-Hy%C3%B4nen_zu_by_Josetsu.jpg', '「丸くすべすべした瓢箪で、ぬるぬるした鯰を押さえるにはどうするか」という禅の問い（公案）を絵にした作品で、将軍足利義持の命で相国寺の画僧・如拙が描いたとされます。画面の上には京都の禅僧31人が答えの詩を書き込んでおり、1415年以前に成立しました。もとは衝立でしたが、後に掛軸に仕立て直されています。川辺の葦や遠くの山を淡い墨でまとめた描き方は、日本の初期水墨画を代表するもので、後の周文や雪舟へ続く流れの出発点となりました。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('水色巒光図', 'Hue of the Water, Light on the Peaks', '周文', 'Tenshō Shūbun',
        1445,
        (select slug from public.art_movements where slug = 'suiboku'),
        '奈良国立博物館', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e5/Landscape_Tensh%C5%8D_Sh%C5%ABbun_painting_part.jpg/960px-Landscape_Tensh%C5%8D_Sh%C5%ABbun_painting_part.jpg', '縦長の画面の下に水辺の山水を描き、上に禅僧たちが詩を書き込んだ「詩画軸」の代表作です。賛の一つに1445年の年記があります。周文の署名はなく「伝周文筆」とされますが、周文の真筆の可能性が高い作品と考えられています。周文は如拙に学び、雪舟の師となった相国寺の画僧です。広い余白を生かしながら、画面の中心に山の軸を立てる構成へと移っていく時期の作品とされ、室町水墨画の山水が成熟していく様子を伝えています。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('四季山水図（山水長巻）', 'Landscape of the Four Seasons', '雪舟', 'Sesshū Tōyō',
        1486,
        (select slug from public.art_movements where slug = 'suiboku'),
        '毛利博物館', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4a/Landscapes_of_the_Four_Seasons_by_Sesshu_%28Mori_Museum%29.jpg/960px-Landscapes_of_the_Four_Seasons_by_Sesshu_%28Mori_Museum%29.jpg', '長さ16メートルに及ぶ長大な画巻で、1486年、雪舟が60代半ばに描いた代表作です。巻物を広げていくと、春から夏、秋、冬へと季節が移り、山道や村、水辺の景色が途切れなく続きます。雪舟は明に渡って中国の絵を学びましたが、この作品では宋・元の古典や明の画風を吸収したうえで、力強い筆の線と自分なりの構成で一つの世界を作り上げています。旧長州藩主の毛利家に伝わり、今も毛利博物館が所蔵し、毎年秋に公開されています。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('破墨山水図', 'Haboku sansui', '雪舟', 'Sesshū Tōyō',
        1495,
        (select slug from public.art_movements where slug = 'suiboku'),
        '東京国立博物館', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/2/27/Sesshu_-_Haboku-Sansui.jpg/960px-Sesshu_-_Haboku-Sansui.jpg', '1495年、76歳の雪舟が弟子の宗淵に与えた山水図です。輪郭線をほとんど使わず、にじむ墨を面で置いていく「破墨」の技法で、霧の中の山や家、舟を一気に描いています。画面の上に雪舟自身が書いた文章では、明へ渡ったが求める師はいなかったと述べ、先輩の如拙や周文をたたえています。日本の画家が自分の画業について語った文章として最も古いものとされ、中国に学びながら日本の水墨画を築いた雪舟の自負が、絵と文章の両方から伝わります。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('天橋立図', 'View of Amanohashidate', '雪舟', 'Sesshū Tōyō',
        1501,
        (select slug from public.art_movements where slug = 'suiboku'),
        '京都国立博物館', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7a/Sesshu_-_View_of_Ama-no-Hashidate.jpg/960px-Sesshu_-_View_of_Ama-no-Hashidate.jpg', '日本三景の一つ、京都府北部の天橋立を、高い所から見下ろすように描いた作品です。署名や印はありませんが、筆づかいや構図、図中に書き込まれた地名の文字から雪舟の筆と考えられ、16世紀初め、晩年の作とみられています。中国の名所を描くことが多かった当時の水墨画の中で、日本の実際の風景をこれほど詳しく描いたのは珍しいことでした。中国画の手本から離れて、自分の目で見た日本の景色を描こうとした雪舟の姿勢がよく表れています。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('周茂叔愛蓮図', 'Zhou Maoshu Admiring Lotuses', '狩野正信', 'Kanō Masanobu',
        1451,
        (select slug from public.art_movements where slug = 'kano'),
        '九州国立博物館', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c5/Zhou_Maoshu_Appreciating_Lotuses.jpg/960px-Zhou_Maoshu_Appreciating_Lotuses.jpg', '狩野派の祖・狩野正信の筆とされる掛軸で、15世紀後半の作品です。蓮の花を愛した北宋の学者・周茂叔（周敦頤）が、舟の上から蓮を眺める故事を描いています。墨を主にしながら、木々に透明感のある淡い色をのせ、すがすがしい画面に仕上げています。中国の故事と水墨画の技法を用いた漢画の作品で、室町幕府の御用絵師となった正信が、相国寺の画僧たちの水墨画を受け継いでいたことがわかります。ここから約400年続く狩野派の歴史が始まりました。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('大仙院 四季花鳥図', 'Birds and Flowers of the Four Seasons', '狩野元信', 'Kanō Motonobu',
        1513,
        (select slug from public.art_movements where slug = 'kano'),
        '大仙院（大徳寺）', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/4/48/Kan%C5%8D_Motonobu_-_Birds_and_Flowers_of_the_Four_Seasons.jpg/960px-Kan%C5%8D_Motonobu_-_Birds_and_Flowers_of_the_Four_Seasons.jpg', '京都・大徳寺の塔頭、大仙院の部屋を飾っていた障壁画で、狩野元信本人が描いたことが確かな貴重な作品です。大仙院が創建された1513年の制作と考えられてきましたが、1535年の改築時とする見方もあります。墨一色で描かれることが多かった当時の水墨画に対し、元信は鳥や草花に鮮やかな色をのせました。中国風の水墨画の力強さと、大和絵の色彩を組み合わせたこの表現は、狩野派の画風の基本となり、後の豪華な障壁画へつながっていきます。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('檜図屏風', 'Cypress Trees', '狩野永徳', 'Kanō Eitoku',
        1590,
        (select slug from public.art_movements where slug = 'kano'),
        '東京国立博物館', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/1/1a/Kano_Eitoku_-_Cypress_Trees_-_Google_Art_Project.jpg/960px-Kano_Eitoku_-_Cypress_Trees_-_Google_Art_Project.jpg', '金地の画面いっぱいに、ねじれながら枝を伸ばす檜の巨木を描いた作品です。豊臣秀吉が八条宮智仁親王のために建てた御殿の襖絵だったもので、1590年12月に完成した屋敷のために描かれたとみられています。永徳は同じ年に亡くなっており、最晩年の作と考えられます。織田信長や豊臣秀吉に仕えた永徳は、城や御殿の広い空間を、大きく力強いモチーフで飾る「大画」を得意としました。桃山時代の権力者の好みと、狩野派の最盛期の勢いをよく伝える作品です。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('金山西湖図屏風', 'Jinshan Island and West Lake', '狩野山楽', 'Kanō Sanraku',
        1630,
        (select slug from public.art_movements where slug = 'kano'),
        'メトロポリタン美術館', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/a/ab/%E9%87%91%E5%B1%B1%E8%A5%BF%E6%B9%96%E5%9B%B3%E5%B1%8F%E9%A2%A8-Jinshan_Island_and_West_Lake_MET_DP704865.jpg/960px-%E9%87%91%E5%B1%B1%E8%A5%BF%E6%B9%96%E5%9B%B3%E5%B1%8F%E9%A2%A8-Jinshan_Island_and_West_Lake_MET_DP704865.jpg', '右の屏風に長江に浮かぶ金山島、左の屏風に杭州の西湖という、中国の二つの名所を描いた六曲一双の屏風です。印章などから1630年ごろの作とされます。別々の場所ですが、岩山や水面、金色の霞でひと続きの景色のようにまとめられています。山楽は狩野永徳の弟子で養子となった絵師で、永徳の死後は豊臣家に仕え、京都に残ってその子孫は「京狩野」と呼ばれました。江戸に移った探幽らとは別の道を歩んだ、もう一つの狩野派の姿がわかります。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('風神雷神図屏風', 'The Gods of Wind and Thunder', '俵屋宗達', 'Tawara Sōtatsu',
        1601,
        (select slug from public.art_movements where slug = 'rinpa'),
        '建仁寺（京都国立博物館寄託）', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/3/37/Wind_God_and_Thunder_God_Screens_by_Tawaraya_Sotatsu_hi-res.png/960px-Wind_God_and_Thunder_God_Screens_by_Tawaraya_Sotatsu_hi-res.png', '江戸時代初期の絵師、俵屋宗達の最高傑作とされる二曲一双の金屏風です。左右の端に雷神と風神を配置し、中央に大きな金地の余白を残す大胆な構図で描かれています。二神の姿は鎌倉時代の『北野天神縁起絵巻』などに学んだものといわれ、大和絵の伝統を新しい装飾的な画面に生まれ変わらせました。署名も印もありませんが、宗達の真筆と認められています。後に尾形光琳や酒井抱一がこの絵を写しており、琳派が私淑によって受け継がれていく出発点となりました。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('風神雷神図屏風（尾形光琳）', 'Wind God and Thunder God', '尾形光琳', 'Ogata Kōrin',
        1701,
        (select slug from public.art_movements where slug = 'rinpa'),
        '東京国立博物館', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/9/9d/Wind_God_and_Thunder_God_Screens_by_Ogata_Korin.png/960px-Wind_God_and_Thunder_God_Screens_by_Ogata_Korin.png', '俵屋宗達の『風神雷神図屏風』を、およそ100年後に尾形光琳が写した作品で、江戸時代中期の作とみられます。宗達の絵を忠実になぞりながら、二神の位置や線、色合いに光琳らしい個性が加えられています。宗達と光琳のあいだに直接の師弟関係はなく、光琳は作品を通して宗達に学びました。後にこの屏風の裏に酒井抱一が『夏秋草図』を描き、さらに鈴木其一も同じ画題を手がけています。比べて見ることで、琳派の継承と変化がよくわかる作品です。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('燕子花図', 'Irises screen', '尾形光琳', 'Ogata Kōrin',
        1701,
        (select slug from public.art_movements where slug = 'rinpa'),
        '根津美術館', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e9/KORIN-Irises-L.jpg/960px-KORIN-Irises-L.jpg', '金地の六曲一双の屏風に、群生する燕子花（かきつばた）の花と葉だけを、群青と緑青で繰り返し描いた作品です。光琳が法橋という位を得た1701年以降、40代半ばごろの代表作とされます。『伊勢物語』の八橋の場面が下敷きにあるといわれますが、人物も橋も描かず、花の配置だけでリズムを生み出しています。同じ形を型紙のように繰り返す手法は、着物の模様にも通じる琳派らしいデザイン感覚です。根津美術館では毎年春に公開されています。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('紅白梅図屏風', 'Red and White Plum Blossoms', '尾形光琳', 'Ogata Kōrin',
        1710,
        (select slug from public.art_movements where slug = 'rinpa'),
        'MOA美術館', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/9/94/Ogata_K%C5%8Drin_-_Red_and_White_Plum_Blossoms.jpg/960px-Ogata_K%C5%8Drin_-_Red_and_White_Plum_Blossoms.jpg', '中央を流れる川をはさんで、右に紅梅、左に白梅が向き合う二曲一双の屏風です。光琳の最晩年の作と考えられ、画業の集大成といわれます。梅の幹には、乾ききらない絵の具に別の色を垂らしてにじませる「たらしこみ」が使われ、花びらは輪郭線を引かない「光琳梅」で表されています。川の水は、うねる模様として図案化されています。写実的な木と、模様のような水の組み合わせが、琳派の装飾性をよく示しています。MOA美術館が所蔵しています。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
