insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('夏秋草図屏風', 'Flowering Plants of Summer and Autumn', '酒井抱一', 'Sakai Hōitsu',
        1821,
        (select slug from public.art_movements where slug = 'rinpa'),
        '東京国立博物館', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/3/35/Summer_and_Autumn_Flower_Plants_%28left%29.jpg/960px-Summer_and_Autumn_Flower_Plants_%28left%29.jpg', '江戸琳派を開いた酒井抱一が、尾形光琳の『風神雷神図屏風』の裏に描いた作品で、1821年ごろの作とされます。雷神の裏には雨に打たれる夏草、風神の裏には風になびく秋草が描かれ、表の絵と呼び合うように工夫されています。金地の表に対して、裏は銀地を使っています。保存のため1975年に表裏が分けられ、別の屏風になりました。宗達から光琳、そして抱一へと、時代を超えて作品を通して受け継がれる琳派の流れを、一つの屏風が物語っています。')
on conflict (title, artist) do update set
