    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('見返り美人図', 'Beauty Looking Back', '菱川師宣', 'Hishikawa Moronobu',
        1690,
        (select slug from public.art_movements where slug = 'ukiyo-e'),
        '東京国立博物館', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/8/81/Hishikawa_Moronobu_-_Beauty_Looking_Back_-_Google_Art_Project.jpg/960px-Hishikawa_Moronobu_-_Beauty_Looking_Back_-_Google_Art_Project.jpg', '浮世絵の祖とされる菱川師宣の代表作で、17世紀後半に絹に筆で描かれた肉筆画です。緋色の着物を着た女性が、歩みを止めてふと後ろを振り返る一瞬の姿をとらえています。背景を描かず、着物の模様や流行の髪型、帯の結び方を細かく描くことで、当時の江戸の女性のおしゃれを伝えています。師宣は落款に「大和絵師」と記しており、大和絵の風俗画の伝統から、町人のための新しい絵を生み出しました。切手の図柄にも使われ、広く親しまれています。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('寛政三美人', 'Three Beauties of the Present Day', '喜多川歌麿', 'Kitagawa Utamaro',
        1793,
        (select slug from public.art_movements where slug = 'ukiyo-e'),
        '東京国立博物館ほか', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6b/Kitagawa_Utamaro_-_Toji_san_bijin_%28Three_Beauties_of_the_Present_Day%29From_Bijin-ga_%28Pictures_of_Beautiful_Women%29%2C_published_by_Tsutaya_Juzaburo_-_Google_Art_Project.jpg/960px-thumbnail.jpg', '寛政5年（1793年）ごろの錦絵で、当時「寛政の三美人」として評判だった富本豊雛、難波屋おきた、高島屋おひさの3人を描いています。一見よく似た顔に見えますが、目や眉、鼻のわずかな違いで3人を描き分け、着物の家紋で誰かがわかるようになっています。背景には雲母（きら）の粉が摺られ、きらめく効果を生んでいます。版元は蔦屋重三郎です。鈴木春信らの型にはまった美人画に比べ、一人ひとりの個性に目を向けた点で、美人画の新しい段階を示す作品です。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('三代目大谷鬼次の江戸兵衛', 'Kabuki Actor Ōtani Oniji III as Yakko Edobei in the Play The Colored Reins of a Loving Wife (Koi nyōbō somewake tazuna)', '東洲斎写楽', 'Sharaku',
        1794,
        (select slug from public.art_movements where slug = 'ukiyo-e'),
        '東京国立博物館ほか', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/b/be/The_actor_Otani_Oniji_II_as_Yakko_Edobei_-_Sharaku_-_TNM.jpg/960px-The_actor_Otani_Oniji_II_as_Yakko_Edobei_-_Sharaku_-_TNM.jpg', '1794年5月に上演された歌舞伎『恋女房染分手綱』で、三代目大谷鬼次が演じた悪役・江戸兵衛を描いた役者絵です。版元は蔦屋重三郎で、写楽が最初に出した役者の大首絵28点の一つです。あごを突き出してにらみつける顔、乱れた髪、前に突き出した両手が、獲物を襲う瞬間の緊張を伝えます。それまでの役者絵が役者を美しく描いたのに対し、写楽は役柄や役者の特徴を誇張してとらえました。写楽の活動は1年に満たず、謎の多い絵師として知られています。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('神奈川沖浪裏', 'The Great Wave off Kanagawa', '葛飾北斎', 'Katsushika Hokusai',
        1830,
        (select slug from public.art_movements where slug = 'ukiyo-e'),
        '東京国立博物館ほか', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b5/Katsushika_Hokusai_-_The_Great_Wave_off_the_Coast_of_Kanagawa_LCCN2008660568.jpg/960px-Katsushika_Hokusai_-_The_Great_Wave_off_the_Coast_of_Kanagawa_LCCN2008660568.jpg', '葛飾北斎の風景版画シリーズ『富嶽三十六景』の一図で、北斎の作品の中でも最も広く世界に知られています。高く巻き上がる大波と、波にもまれる3艘の舟、その向こうに小さく見える富士山という劇的な構図です。シリーズでは輸入顔料のベロ藍が効果的に使われました。当時5000〜8000枚が摺られたと推測されており、現在も世界各地の美術館に残っています。作曲家ドビュッシーがこの図を楽譜の表紙に使うなど、ジャポニスムを通じて西洋の芸術家にも影響を与えました。')
on conflict (title, artist) do update set
