    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('名所江戸百景 大はしあたけの夕立', 'Sudden Shower over Shin-Ōhashi Bridge and Atake', '歌川広重', 'Utagawa Hiroshige',
        1857,
        (select slug from public.art_movements where slug = 'ukiyo-e'),
        'メトロポリタン美術館ほか', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/2/26/Utagawa_Hiroshige_-_Evening_Shower_at_Atake_and_the_Great_Bridge.jpg/960px-Utagawa_Hiroshige_-_Evening_Shower_at_Atake_and_the_Great_Bridge.jpg', '歌川広重の晩年のシリーズ『名所江戸百景』の一枚です。隅田川にかかる新大橋（大はし）を、激しい夕立の中、急いで渡る人々が描かれています。雨を細い直線の重なりで表す描き方は、当時としては斬新なものでした。遠くの対岸は雨にかすみ、画面全体に湿った空気が感じられます。このシリーズはよく売れ、広重の代表作となりました。オランダの画家ゴッホはこの絵を油絵で模写しており、浮世絵がヨーロッパの画家に与えた影響をよく示す例となっています。')
on conflict (title, artist) do update set
