    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('十便図', 'Ten Advantages', '池大雅', 'Ike no Taiga',
        1771,
        (select slug from public.art_movements where slug = 'nanga'),
        '川端康成記念会', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/4/49/%E6%B1%A0%E5%A4%A7%E9%9B%85%E3%80%8A%E5%8D%81%E4%BE%BF%E5%9B%B3_%E9%87%A3%E4%BE%BF%E5%9B%B3%E3%80%8B1771%E5%B9%B4%E3%80%81%E5%B7%9D%E7%AB%AF%E5%BA%B7%E6%88%90%E8%A8%98%E5%BF%B5%E4%BC%9A.jpg/960px-%E6%B1%A0%E5%A4%A7%E9%9B%85%E3%80%8A%E5%8D%81%E4%BE%BF%E5%9B%B3_%E9%87%A3%E4%BE%BF%E5%9B%B3%E3%80%8B1771%E5%B9%B4%E3%80%81%E5%B7%9D%E7%AB%AF%E5%BA%B7%E6%88%90%E8%A8%98%E5%BF%B5%E4%BC%9A.jpg', '明末から清初の中国の文人、李漁が山荘暮らしの楽しみを詠んだ詩をもとに、池大雅が「十の便利さ」を10図に描いた画帖です。同じ詩の「十の宜しさ」を与謝蕪村が描いた『十宜図』と組になり、1771年ごろに完成しました。依頼したのは鳴海宿の豪商・下郷学海で、作家の川端康成が後に所蔵しました。各図は約18センチ四方の小さな画面で、手に取って楽しむことができます。大雅のおおらかで軽やかな筆づかいからは、中国の文人の生活にあこがれた南画の精神が伝わってきます。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('十宜図', 'Ten Pleasures', '与謝蕪村', 'Yosa Buson',
        1771,
        (select slug from public.art_movements where slug = 'nanga'),
        '川端康成記念会', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/2/24/%E4%B8%8E%E8%AC%9D%E8%95%AA%E6%9D%91%E3%80%8A%E5%8D%81%E5%AE%9C%E5%9B%B3_%E5%AE%9C%E6%9A%81%E5%9B%B3%E3%80%8B1771%E3%80%81%E5%B7%9D%E7%AB%AF%E5%BA%B7%E6%88%90%E8%A8%98%E5%BF%B5%E4%BC%9A.jpg/960px-%E4%B8%8E%E8%AC%9D%E8%95%AA%E6%9D%91%E3%80%8A%E5%8D%81%E5%AE%9C%E5%9B%B3_%E5%AE%9C%E6%9A%81%E5%9B%B3%E3%80%8B1771%E3%80%81%E5%B7%9D%E7%AB%AF%E5%BA%B7%E6%88%90%E8%A8%98%E5%BF%B5%E4%BC%9A.jpg', '李漁の詩にうたわれた山荘の「十の宜しさ」を、与謝蕪村が10図に描いた画帖で、池大雅の『十便図』と組になっています。1771年ごろの完成です。同じ時代に文人画を志しながら、ほとんど交流のなかった大雅と蕪村が、同じ題材に取り組んだことで知られます。蕪村は俳人としても名高く、季節の移ろいや天気の変化を、淡い色とやわらかな筆で詩情豊かに描きました。二人の個性の違いを見比べられる点で、江戸時代の南画が大成したことを示す作品です。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('夜色楼台図', 'Snowclad Houses in the Night', '与謝蕪村', 'Yosa Buson',
        1778,
        (select slug from public.art_movements where slug = 'nanga'),
        '個人蔵', 'https://upload.wikimedia.org/wikipedia/commons/a/a6/Snowclad_houses_in_the_night.jpg', '雪の降り積もった夜の町並みを、横に長い画面に描いた与謝蕪村の晩年の作品です。1778年から1783年ごろの制作と考えられています。夜空を墨で暗く塗り込めることで、屋根に積もった雪の白さを際立たせ、家々には人の暮らしの気配が感じられます。背後には雪をかぶった山並みが静かに続きます。中国の文人画の技法を用いながら、描かれているのは日本の冬の町の情景です。俳人でもあった蕪村の、静けさと温かさを同時に感じさせる詩的な表現が見どころです。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('東雲篩雪図', 'Snow Sifted Through Frozen Clouds', '浦上玉堂', 'Uragami Gyokudō',
        1811,
        (select slug from public.art_movements where slug = 'nanga'),
        '川端康成記念会', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/7/70/%E6%B5%A6%E4%B8%8A%E7%8E%89%E5%A0%82%E3%80%8A%E6%9D%B1%E9%9B%B2%E7%AF%A9%E9%9B%AA%E5%9B%B3%E3%80%8B19%E4%B8%96%E7%B4%80%E3%80%81%E5%B7%9D%E7%AB%AF%E5%BA%B7%E6%88%90%E8%A8%98%E5%BF%B5%E4%BC%9A.jpg/960px-%E6%B5%A6%E4%B8%8A%E7%8E%89%E5%A0%82%E3%80%8A%E6%9D%B1%E9%9B%B2%E7%AF%A9%E9%9B%AA%E5%9B%B3%E3%80%8B19%E4%B8%96%E7%B4%80%E3%80%81%E5%B7%9D%E7%AB%AF%E5%BA%B7%E6%88%90%E8%A8%98%E5%BF%B5%E4%BC%9A.jpg', '浦上玉堂が60代の終わりごろに描いたと推定される、玉堂の最高傑作とされる作品です。雪がふるいにかけたように降る冬の山を、墨の濃淡と、こすりつけるような細かな筆の重なりで表しています。文化財としての登録名は『凍雲篩雪図』ですが、玉堂自身は『東雲篩雪図』と名付けました。玉堂は武士の身分を捨てて琴と絵を友に各地を旅した文人で、その作品は形よりも心の動きを重んじています。この絵を高く評価した作家の川端康成が購入し、所蔵したことでも知られます。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('鷹見泉石像', 'Portrait of Takami Senseki', '渡辺崋山', 'Watanabe Kazan',
        1837,
        (select slug from public.art_movements where slug = 'nanga'),
        '東京国立博物館', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/7/74/A_portrait_of_Takami_Senseki_by_Watanabe_Kazan.jpg/960px-A_portrait_of_Takami_Senseki_by_Watanabe_Kazan.jpg', '古河藩の家老で蘭学者でもあった鷹見泉石を、渡辺崋山が1837年に描いた肖像画です。背景を描かない正装の姿ですが、頬や目のまわりには西洋画の陰影法が使われ、顔に立体感が生まれています。淡い彩色は水彩画を思わせます。崋山は南画家の谷文晁に学びつつ、蘭学を通して西洋の絵画にも関心をもちました。南画の筆づかいと西洋の写実を組み合わせたこの作品は、江戸時代の終わりに、日本の絵画が西洋と出会い始めていたことを示しています。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('鮭', 'Salmon', '高橋由一', 'Takahashi Yuichi',
        1877,
        (select slug from public.art_movements where slug = 'yoga-meiji'),
        '東京藝術大学大学美術館', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/c/ca/Salmon_by_Takahashi_Yuichi_%28Geidai_Museum%29.jpg/960px-Salmon_by_Takahashi_Yuichi_%28Geidai_Museum%29.jpg', '縄でつるされ、半身が切り取られた塩鮭を、縦長の画面に描いた油彩画で、1877年ごろの作とされます。高橋由一は幕末から西洋画を学び、明治初期に油絵の技法で身近なものを描き続けた先駆者です。うろこの光、皮のざらつき、切り口の赤い身の質感が、驚くほど細かく描き込まれています。油絵具ならではの質感の表現に、由一が西洋画から学んだことがよく表れています。日本の洋画の出発点を示す作品として、教科書や切手でも親しまれています。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('騎竜観音', 'Guanyin riding the dragon', '原田直次郎', 'Harada Naojirō',
        1890,
        (select slug from public.art_movements where slug = 'yoga-meiji'),
        '護国寺（東京国立近代美術館寄託）', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/0/03/Kannon_Riding_a_Dragon_by_Harada_Naojiro_%28National_Museum_of_Modern_Art%2C_Tokyo%29.jpg/960px-Kannon_Riding_a_Dragon_by_Harada_Naojiro_%28National_Museum_of_Modern_Art%2C_Tokyo%29.jpg', '雲間を進む竜の背に乗った観音を、西洋の油彩技法で描いた大作で、1890年の作品です。原田直次郎はドイツのミュンヘンでガブリエル・フォン・マックスに学び、1887年に帰国しました。当時の日本では西洋画を退ける空気が強まっていましたが、原田は伝統的な仏教の題材を、写実的な陰影や立体感をもつ油絵で描くことで、洋画の可能性を示そうとしました。発表当時は大きな議論を呼んだ作品です。現在は護国寺が所有し、東京国立近代美術館に預けられています。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('湖畔', 'Lakeside', '黒田清輝', 'Kuroda Seiki',
        1897,
        (select slug from public.art_movements where slug = 'yoga-meiji'),
        '東京国立博物館', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/1/18/Kuroda-seiki-kohan00-6-1b.jpeg/960px-Kuroda-seiki-kohan00-6-1b.jpeg', '箱根の芦ノ湖のほとりで、浴衣姿の女性が団扇を手に涼んでいる様子を描いた油彩画で、1897年の作品です。モデルは後に黒田の妻となった金子たねです。フランスで外光派のラファエル・コランに学んだ黒田は、明るい光や空気を淡い色調で表す画風を日本に伝えました。この作品では、湖面や遠くの山を薄い水色でまとめ、夏のさわやかな空気を感じさせます。西洋の技法で日本の人物と風景を描いた、明治の洋画を代表する作品として親しまれています。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('グレーの洗濯場', 'Washing Place in Grez-sur-Loing', '浅井忠', 'Asai Chū',
        1901,
        (select slug from public.art_movements where slug = 'yoga-meiji'),
        'アーティゾン美術館', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d5/Asai_Chu_-_Washing_Place_in_Grez-sur-Loing_-_Google_Art_Project.jpg/960px-Asai_Chu_-_Washing_Place_in_Grez-sur-Loing_-_Google_Art_Project.jpg', '浅井忠が1900年からのフランス留学中、1901年に描いた作品です。グレー＝シュル＝ロワンは、パリ近郊の川沿いの村で、黒田清輝をはじめ多くの画家が滞在した芸術家村として知られます。浅井は工部美術学校でイタリア人画家フォンタネージに学び、明治美術会の中心として活躍した画家です。この作品では、川辺の洗濯場の静かな景色を、落ち着いた色合いで丁寧にとらえています。浅井は留学中にアール・ヌーヴォーにも影響を受け、帰国後はデザインの分野でも活動しました。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('天平の面影', 'Reminiscence of the Tempyō Era', '藤島武二', 'Fujishima Takeji',
        1902,
        (select slug from public.art_movements where slug = 'yoga-meiji'),
        'アーティゾン美術館', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/3/32/Reminiscence_of_the_Tempyo_Era_%28Fujishima_Takeji%29.jpg/960px-Reminiscence_of_the_Tempyo_Era_%28Fujishima_Takeji%29.jpg', '奈良時代（天平時代）の衣装をまとった女性が、古代の竪琴である箜篌（くご）を持って立つ姿を、金色の背景に描いた油彩画で、1902年の作品です。藤島武二は黒田清輝の白馬会に加わり、東京美術学校で教えた画家です。西洋の油絵の技法を使いながら、日本の古代という題材を取り上げ、装飾的で夢のような雰囲気に仕上げています。明治の洋画が、写実だけでなく、日本の歴史や物語を描くロマン主義的な方向へも広がっていったことを示す作品です。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('わだつみのいろこの宮', 'Paradise Under the Sea', '青木繁', 'Shigeru Aoki',
        1907,
        (select slug from public.art_movements where slug = 'yoga-meiji'),
        'アーティゾン美術館', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/a/af/AOKI_Shigeru_-_Paradise_under_the_Sea.jpg/960px-AOKI_Shigeru_-_Paradise_under_the_Sea.jpg', '日本神話の山幸彦が、海の神の宮殿を訪れ、豊玉姫と出会う場面を描いた油彩画で、1907年の作品です。同じ年の東京府勧業博覧会で三等賞を受けました。縦長の画面に、青い海の底の光と、木の上の山幸彦を見上げる女性たちが幻想的に描かれています。青木繁は明治の絵画のロマン主義的な傾向を代表する画家で、イギリスのロマン主義の絵画からの影響もうかがえます。28歳で亡くなった青木の、神話を題材にした作品群の到達点とされています。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('悲母観音', 'Avalokitesvara as a Merciful Mother', '狩野芳崖', 'Kanō Hōgai',
        1888,
        (select slug from public.art_movements where slug = 'nihonga'),
        '東京藝術大学大学美術館', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/a/ad/Kan%C5%8D_H%C5%8Dgai_-_Hibo_kannon_%28Avalokitesvara_as_a_Merciful_Mother%29.jpg/960px-Kan%C5%8D_H%C5%8Dgai_-_Hibo_kannon_%28Avalokitesvara_as_a_Merciful_Mother%29.jpg', '天から観音が浄瓶の水を注ぎ、その下の球の中に生まれたばかりの赤ん坊が浮かぶ姿を描いた作品で、1888年に完成した狩野芳崖の絶筆です。芳崖は狩野派の出身で、フェノロサとともに日本画の革新に取り組みました。狩野派で鍛えた確かな線描に、明るく澄んだ色彩や、空間の奥行きを感じさせる表現が加わっています。伝統と新しさが一つの画面で結びついたこの作品は、芳崖が目指した日本画革新の到達点であり、近代日本画の出発点とみなされています。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('水鏡', 'Reflection in the Water', '菱田春草', 'Hishida Shunsō',
        1897,
        (select slug from public.art_movements where slug = 'nihonga'),
        '東京藝術大学大学美術館', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f8/Hishida_Shuns%C5%8D_-_Reflection_in_the_Water.jpg/960px-Hishida_Shuns%C5%8D_-_Reflection_in_the_Water.jpg', '紫陽花のそばで、美しい天女が水面に映る自分の姿を見つめている作品で、1897年、菱田春草が23歳のときに描きました。日本絵画協会の共進会に出品されています。美しさも時がたてば衰えるという意味が込められているといわれます。春草は岡倉天心の門下で、横山大観や下村観山とともに明治の日本画の革新に取り組みました。この作品では、まだ線描を生かした描き方ですが、淡い色合いと静かな空気感に、のちに輪郭線を使わない新しい表現へ向かう春草の感性が表れています。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('木の間の秋', 'Autumn among Trees', '下村観山', 'Kanzan Shimomura',
        1907,
        (select slug from public.art_movements where slug = 'nihonga'),
        '東京国立近代美術館', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a2/Shimomura_Kanzan_-_Autumn_among_Trees.jpg/960px-Shimomura_Kanzan_-_Autumn_among_Trees.jpg', '秋の林の木々を、二曲一双の屏風に描いた下村観山の代表作で、1907年の作品です。観山は岡倉天心の門下で日本美術院の創立に加わり、1903年から1905年ごろにかけてイギリスに留学しました。この作品では、大和絵や琳派の装飾的な技法に、西洋画から学んだ写実的な表現を組み合わせています。木の幹に付いた地衣類（コケのような生き物）まで細かく描かれているのが見どころです。伝統の技法を土台に、西洋の目も取り入れた明治の日本画の姿がよくわかります。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('焔', 'Flames', '上村松園', 'Shoen Uemura',
        1918,
        (select slug from public.art_movements where slug = 'nihonga'),
        '東京国立博物館', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0e/Uemura-Flame-1918.jpg/960px-Uemura-Flame-1918.jpg', '能の『葵上』に登場する六条御息所をもとに、嫉妬の心から生霊となった女性を描いた作品で、1918年の文展に出品されました。長い黒髪の端を口にくわえ、振り返るように立つ女性の着物には、蜘蛛の巣と藤の花の模様が描かれています。清らかで気品のある美人画を得意とした上村松園にとって、本人が「たった一枚の凄艶な絵」と語った異色の代表作です。伝統的な題材と技法を用いながら、人の心の深い部分を表そうとした、近代日本画ならではの作品です。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('谿山行旅図', 'Travelers Among Mountains and Streams', '范寛', 'Fan Kuan',
        1000,
        (select slug from public.art_movements where slug = 'song-yuan'),
        '国立故宮博物院（台北）', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b1/%E8%B0%BF%E5%B1%B1%E8%A1%8C%E6%97%85%E5%9B%BE%E8%BD%B4.%E6%BA%AA%E5%B1%B1%E8%A1%8C%E6%97%85%E5%9B%BE.%E5%AE%8B.%E8%8C%83%E5%AE%BD.%E7%BB%A2%E6%9C%AC%E6%B5%85%E8%AE%BE%E8%89%B2.%E5%8F%B0%E5%8C%97%E6%95%85%E5%AE%AB%E5%8D%9A%E7%89%A9%E9%99%A2%E8%97%8F.jpg/960px-%E8%B0%BF%E5%B1%B1%E8%A1%8C%E6%97%85%E5%9B%BE%E8%BD%B4.%E6%BA%AA%E5%B1%B1%E8%A1%8C%E6%97%85%E5%9B%BE.%E5%AE%8B.%E8%8C%83%E5%AE%BD.%E7%BB%A2%E6%9C%AC%E6%B5%85%E8%AE%BE%E8%89%B2.%E5%8F%B0%E5%8C%97%E6%95%85%E5%AE%AB%E5%8D%9A%E7%89%A9%E9%99%A2%E8%97%8F.jpg', '北宋の初めごろに活躍した范寛の代表作で、北宋の山水画を代表する作品です。画面の上半分に巨大な岩山がそびえ立ち、その足もとの道を、荷物を積んだ馬を連れた旅人の一行が小さく進んでいきます。手前の岩と道、中ほどの霧と水、奥の山という三つの層で、雄大な奥行きを表しています。范寛は自然そのものを師として学んだと伝えられます。木々の中に隠れるように書かれた署名は、1958年になって再発見されました。人間の小ささと自然の大きさを感じさせる一枚です。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('山径春行図', 'Walking on a Mountain Path in Spring', '馬遠', 'Ma Yuan',
        1190,
        (select slug from public.art_movements where slug = 'song-yuan'),
        '国立故宮博物院（台北）', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/1/12/%E5%90%8D%E7%BB%98%E9%9B%86%E7%8F%8D%E5%86%8C_13_%E5%8D%97%E5%AE%8B_%E9%A9%AC%E8%BF%9C_%E5%B1%B1%E5%BE%84%E6%98%A5%E8%A1%8C.jpg/960px-%E5%90%8D%E7%BB%98%E9%9B%86%E7%8F%8D%E5%86%8C_13_%E5%8D%97%E5%AE%8B_%E9%A9%AC%E8%BF%9C_%E5%B1%B1%E5%BE%84%E6%98%A5%E8%A1%8C.jpg', '南宋の宮廷画家・馬遠が描いた小さな画帖の一図です。画面の左下に、柳の枝が垂れる山道を歩く文人と従者が描かれ、右上には大きな余白が広がっています。余白には、南宋の皇帝・寧宗の作とされる詩が書き込まれています。主な景色を画面の片隅に寄せて描くこのような構図は、馬遠と夏珪によって完成され、「辺角の景」とも呼ばれます。何も描かれていない部分が、春のやわらかな空気や静けさを感じさせます。日本の室町時代の水墨画にも大きな影響を与えました。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('六柿図', 'Six Persimmons', '牧谿', 'Muqi',
        1201,
        (select slug from public.art_movements where slug = 'song-yuan'),
        '龍光院（大徳寺）', 'https://upload.wikimedia.org/wikipedia/commons/c/c7/%E5%85%AD%E6%9F%BF%E5%9B%BE.jpg', '南宋末の禅僧・牧谿の作と伝えられる作品で、13世紀に描かれました。横一列に並んだ六つの柿を、墨の濃さと筆づかいだけで描き分けています。濃い墨の柿、輪郭だけの淡い柿が並び、何もない背景の中で静かな緊張を生んでいます。禅の考え方を表す作品としてよく紹介されます。牧谿の絵は日本へ渡り、室町時代には将軍家などが大切にしました。中国本国よりも日本で高く評価された画家で、京都・大徳寺の龍光院に伝わるこの作品も、ごくまれにしか公開されません。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('李白吟行図', 'Li Bo in Stroll', '梁楷', 'Liang Kai',
        1201,
        (select slug from public.art_movements where slug = 'song-yuan'),
        '東京国立博物館', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f8/Liang_Kai_-_Li_Bai_Strolling.jpg/960px-Liang_Kai_-_Li_Bai_Strolling.jpg', '唐の詩人・李白が、夕暮れの中を詩を口ずさみながら歩く姿を描いた作品で、南宋時代、13世紀のものです。輪郭や衣のひだを、ごく少ない筆のタッチでさっと描く「減筆体」の代表作として知られます。梁楷は南宋の画院に属しながら、自ら「梁風子（梁の狂人）」と名乗った自由な人物でした。画面には元時代の収蔵印が押されており、後に日本へ渡って、出雲松江藩主の松平不昧が所蔵しました。少ない線で人物の心まで伝える表現は、日本の水墨画家たちの手本となりました。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('富春山居図', 'Dwelling in the Fuchun Mountains', '黄公望', 'Huang Gongwang',
        1350,
        (select slug from public.art_movements where slug = 'song-yuan'),
        '国立故宮博物院（台北）・浙江省博物館', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6d/%E5%AF%8C%E6%98%A5%E5%B1%B1%E5%B1%85%E5%9C%96%28%E7%84%A1%E7%94%A8%E5%B8%AB%E5%8D%B7%29.jpg/960px-%E5%AF%8C%E6%98%A5%E5%B1%B1%E5%B1%85%E5%9C%96%28%E7%84%A1%E7%94%A8%E5%B8%AB%E5%8D%B7%29.jpg', '元末四大家の一人、黄公望が描いた長い画巻で、1350年に完成しました。浙江省の富春江の流れに沿って、なだらかな山や林、水辺の村が穏やかに続いていきます。黄公望は本格的に絵を始めたのが50歳を過ぎてからといわれる文人画家で、北宋以前の江南の山水画を手本としながら、乾いた筆を重ねて山の質感を表しました。この画巻は後に火災で二つに分かれ、現在は台北と浙江省で別々に所蔵されています。明・清の文人画家たちに手本とされ、日本の南画にもつながる作品です。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('夢遊桃源図', 'Dream Journey to the Peach Blossom Land', '安堅', 'An Kyŏn',
        1447,
        (select slug from public.art_movements where slug = 'joseon'),
        '天理大学附属天理図書館', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/9/93/Dream_Journey_to_the_Peach_Blossom_Land.jpg/960px-Dream_Journey_to_the_Peach_Blossom_Land.jpg', '朝鮮王朝初期の画家・安堅が1447年に描いた山水画で、王子の安平大君が夢で見た理想郷（桃源郷）を、淡い墨と色で描いています。わずか3日で完成したと伝えられます。画面の左から右へ、現実の山道から険しい岩山を越えて、桃の花が咲く理想郷へとたどる構成です。安堅の山水は北宋の郭煕の画風を受け継いでおり、宋の絵画が朝鮮で古典として学ばれていたことがわかります。安平大君ら21人の文章が添えられています。現在は日本の天理図書館が所蔵しています。')
