    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('仁王霽色図', 'Inwang jesaekdo', '鄭敾', 'Jeong Seon',
        1751,
        (select slug from public.art_movements where slug = 'joseon'),
        '国立中央博物館（韓国）', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a7/Inwangjesaekdo.jpg/960px-Inwangjesaekdo.jpg', 'ソウルの仁王山が、雨上がりに霧の間から姿を現す様子を描いた作品で、1751年、鄭敾が晩年に描きました。濃い墨を力強く重ねた岩肌と、白く流れる霧の対比が見どころです。鄭敾は、中国の名所ではなく朝鮮の実際の山や川を描く「真景山水画」を確立した画家で、金剛山など各地の名勝を旅して描きました。中国の手本から学んだ技法を、身近な風景を描くために使った点に、朝鮮王朝後期の絵画の新しさがあります。サムスングループ会長家から国立中央博物館に寄贈されました。')
on conflict (title, artist) do update set
