    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('青銅器と花の静物図屏風', 'Still life with bronze vessels and flowering plants', '張承業', 'Jang Seung-eop',
        1894,
        (select slug from public.art_movements where slug = 'joseon'),
        'メトロポリタン美術館', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/7/77/Still_life_with_bronze_vessels_and_flowering_plants_-_MET_2014.247.jpg/960px-Still_life_with_bronze_vessels_and_flowering_plants_-_MET_2014.247.jpg', '古い青銅器と花の咲く枝を組み合わせて描いた十曲の屏風で、1894年の作品です。左端に張承業の署名と印があります。古い器物と草花を描く静物画は、19世紀の朝鮮で独立した画題として広まりました。描かれた青銅器は、清の時代の中国の器を誇張し、図案化したものとされています。張承業は金弘道・申潤福と並んで「三園」と呼ばれる朝鮮王朝末期の画家です。字が読めなかったため弟子が代わりに署名した例もあるとされ、19世紀末の静物画の屏風として貴重な作品です。')
